INSERT INTO quality_event (code, study_site_id, kind, severity, state, title, detail, category, raised_by, raised_on, capa_plan, capa_owner_account_id, capa_due_on, closed_at, closed_by, resolution) VALUES ('QI-2026-0155', '915ff2c3-4a1a-5549-af44-29eb0f4dc9d0', 'sae_late', 'major', 'open', 'SAE 上报超窗', '受试者 S-0217 发生 3 级肝功能异常，研究者知晓至上报申办方 26.5 小时，超出 24 小时窗口。', 'SAE 上报超窗', 'cra', '2026-08-19', '重新培训 PI 及研究护士 SAE 上报流程；在中心张贴 24h 倒计时卡；CRC 每日核查病历新增 SAE。', 'afa98104-e4ce-5dae-932d-b0b3818255c6', '2026-08-26', NULL, NULL, NULL);
INSERT INTO quality_event (code, study_site_id, kind, severity, state, title, detail, category, raised_by, raised_on, capa_plan, capa_owner_account_id, capa_due_on, closed_at, closed_by, resolution) VALUES ('QI-2026-0139', 'a7a32e26-70ac-5ce4-ba1a-64d3e4e104e4', 'other', 'critical', 'open', '知情同意版本错误', '3 例受试者签署 ICF V2.1（现行版本为 V3.0，2026-05-30 生效），涉及筛选期受试者。', '知情同意版本错误', 'institution', '2026-08-11', '已上报伦理委员会并获批重新签署；全部在筛受试者 ICF 版本 100% 复核；中心文件夹版本控制表上墙。', 'df9f9042-a3df-5980-b0e3-72d6797a4f73', '2026-08-29', NULL, NULL, NULL);
INSERT INTO quality_event (code, study_site_id, kind, severity, state, title, detail, category, raised_by, raised_on, capa_plan, capa_owner_account_id, capa_due_on, closed_at, closed_by, resolution) VALUES ('QI-2026-0142', '0b08f031-8d02-53b8-a193-819317b4bc15', 'deviation', 'major', 'pending_review', '方案偏离', '受试者 S-0331 第 4 次访视实际日期超出方案窗口 5 天（窗口 ±3 天）。', '方案偏离', 'cra', '2026-08-14', 'CRC 增加访视窗口前 7 天提醒机制；PI 签署方案偏离表并上报伦理。', 'd9857040-ed68-5ae8-9351-cfdd35f3cb28', '2026-08-24', NULL, NULL, NULL);
INSERT INTO quality_event (code, study_site_id, kind, severity, state, title, detail, category, raised_by, raised_on, capa_plan, capa_owner_account_id, capa_due_on, closed_at, closed_by, resolution) VALUES ('QI-2026-0151', 'db17fa41-c806-58af-b716-7324d07084b2', 'other', 'minor', 'open', '源数据缺陷', '稽查抽查 20 份原始病历，12 处研究者签名/日期缺失，主要集中在合并用药记录页。', '源数据缺陷', 'sponsor', '2026-08-17', '研究者集中补签并留痕；CRC 建立每周源数据完整性自查清单。', '484f9e15-52f9-57a8-af68-7a56fbe16e0c', '2026-09-05', NULL, NULL, NULL);
INSERT INTO quality_event (code, study_site_id, kind, severity, state, title, detail, category, raised_by, raised_on, capa_plan, capa_owner_account_id, capa_due_on, closed_at, closed_by, resolution) VALUES ('QI-2026-0158', 'ee57f7b2-4cb5-5ff7-a318-77f1633eb6a6', 'other', 'minor', 'pending_review', '药品温控中断', '药房冷藏柜温度记录仪断电 4 小时，期间温度记录缺失，涉及 2 个批次试验用药品。', '药品温控中断', 'site', '2026-08-20', '申办方已出具药品可用性评估；加装 UPS 与温度越限短信报警。', '8ffe778e-9704-5cf1-a979-c31ea1a49cc1', '2026-09-02', NULL, NULL, NULL);
INSERT INTO quality_event (code, study_site_id, kind, severity, state, title, detail, category, raised_by, raised_on, capa_plan, capa_owner_account_id, capa_due_on, closed_at, closed_by, resolution) VALUES ('QI-2026-0146', '44cb314d-e661-5594-b207-97efc0c52b30', 'other', 'major', 'open', '机构质控发现 · 知情同意', '机构二级质控抽查 5 例，发现 3 例受试者签署 ICF V2.1（现行版本 V3.0，2026-05-30 生效）。', '知情同意', 'institution', '2026-08-14', NULL, '1c8425f6-c481-5938-b156-8caddcc5239c', '2026-08-28', NULL, NULL, NULL);
INSERT INTO quality_event (code, study_site_id, kind, severity, state, title, detail, category, raised_by, raised_on, capa_plan, capa_owner_account_id, capa_due_on, closed_at, closed_by, resolution) VALUES ('QI-2026-0147', '44cb314d-e661-5594-b207-97efc0c52b30', 'other', 'major', 'open', '机构质控发现 · 人员资质', '新入组研究护士周琳未提供 GCP 证书，且未列入研究者授权分工表，已参与 3 例受试者访视。', '人员资质', 'institution', '2026-08-14', NULL, '1c8425f6-c481-5938-b156-8caddcc5239c', '2026-08-26', NULL, NULL, NULL);
