INSERT INTO quality_event (code, study_site_id, kind, severity, state, title, detail, category, raised_by, raised_on, capa_plan, capa_owner_account_id, capa_due_on, closed_at, closed_by, resolution) VALUES ('QI-2026-0148', '44cb314d-e661-5594-b207-97efc0c52b30', 'other', 'major', 'open', '监查覆盖不足', '申办方稽查发现：合并用药页 4 处研究者签名缺日期，该问题在此前两次 IMV 的 SDV 中均未被识别 —— SDV 覆盖率 88%，但抽样范围未包含合并用药页。', '监查覆盖不足', 'sponsor', '2026-08-16', '修订 SDV 抽样策略，将合并用药与 AE 页列为每次 IMV 的必查范围；对该中心既往全部受试者回溯复核并留痕。', '374a53e7-95ee-5aca-87af-e56090580112', '2026-09-04', NULL, NULL, NULL);
